import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as i,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Copilot Cookbook","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/copilot/copilot-cookbook.md","filePath":"products/ai-coding/copilot/copilot-cookbook.md","lastUpdated":1787110548000}'),n={name:"products/ai-coding/copilot/copilot-cookbook.md"};function o(l,e,r,p,h,d){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="copilot-cookbook" tabindex="-1">Copilot Cookbook <a class="header-anchor" href="#copilot-cookbook" aria-label="Permalink to &quot;Copilot Cookbook&quot;">​</a></h1><blockquote><p>This is a <strong>task-oriented</strong> page — each section solves one problem; skip to the one you need. Concepts: <a href="./copilot-glossary.html">Glossary</a>. Parameters: <a href="./copilot-cheatsheet.html">Cheatsheet</a>. From zero: <a href="./copilot.html">Tutorial</a>.</p><p>Prerequisite: Copilot is installed and you are signed in. See the <a href="./copilot.html">tutorial</a>.</p></blockquote><h2 id="prompting-principles" tabindex="-1">Prompting principles <a class="header-anchor" href="#prompting-principles" aria-label="Permalink to &quot;Prompting principles&quot;">​</a></h2><p>Read these two PE primers first, then the Copilot-specific notes below:</p><ul><li><a href="https://dev.to/github/a-beginners-guide-to-prompt-engineering-with-github-copilot-3ibp" target="_blank" rel="noreferrer">A Beginner&#39;s Guide to Prompt Engineering with GitHub Copilot</a> — if you have never used Copilot or prompt engineering</li><li><a href="https://learn.deeplearning.ai/courses/chatgpt-prompt-eng/lesson/1/introduction" target="_blank" rel="noreferrer">ChatGPT Prompt Engineering for Developers</a> — Andrew Ng with OpenAI engineers</li></ul><h3 id="simple-tasks-the-3s-rule" tabindex="-1">Simple tasks: the 3S rule <a class="header-anchor" href="#simple-tasks-the-3s-rule" aria-label="Permalink to &quot;Simple tasks: the 3S rule&quot;">​</a></h3><p><strong>Simple, Specific, Short.</strong></p><table tabindex="0"><thead><tr><th>❌ bad</th><th>✅ good</th></tr></thead><tbody><tr><td>write a function that handles the data</td><td>Write a function that takes <code>User[]</code>, sorts by <code>createdAt</code> descending, and returns the first 10</td></tr><tr><td>optimize this</td><td>Rewrite this <code>for</code> loop as <code>reduce</code> and keep the behavior identical</td></tr><tr><td>add some tests</td><td>Write Jest tests for <code>calculateTotal</code> covering empty array, one element, and negative numbers</td></tr></tbody></table><p>The left column is not &quot;too short.&quot; It has <strong>no verifiable done-state</strong>, so Copilot has to guess.</p><h3 id="complex-tasks-background-first-then-one-step-at-a-time" tabindex="-1">Complex tasks: background first, then one step at a time <a class="header-anchor" href="#complex-tasks-background-first-then-one-step-at-a-time" aria-label="Permalink to &quot;Complex tasks: background first, then one step at a time&quot;">​</a></h3><p>Dump a large job in one shot and Copilot will decide things you did not expect. Align context, then walk:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Turn 1: This repo is Next.js 15 App Router + Drizzle ORM on Postgres.</span></span>
<span class="line"><span>        I need a user-export-to-CSV feature.</span></span>
<span class="line"><span>        Do not write code yet. Tell me which files you would change</span></span>
<span class="line"><span>        and which endpoints you would add.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Turn 2: (after you accept the plan) Implement the server action only. No UI.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Turn 3: Add the trigger button. Use the existing &lt;Button&gt; component.</span></span></code></pre></div><p>The value of three turns is that <strong>you can verify at the end of each one</strong>. One giant dump hides which judgment failed.</p><h3 id="context-injection-highest-leverage-move" tabindex="-1">Context injection: highest leverage move <a class="header-anchor" href="#context-injection-highest-leverage-move" aria-label="Permalink to &quot;Context injection: highest leverage move&quot;">​</a></h3><p>Cheapest first:</p><ol><li><strong>Open the relevant files</strong> — open editor tabs enter the context. Open module B before you change A.</li><li><strong>Cite explicitly</strong> — <code>#file:path</code> beats &quot;go find it.&quot;</li><li><strong>Select, then ask</strong> — the selection becomes the focus.</li><li><strong>Write custom instructions</strong> — pay once, every later turn benefits. See <a href="./copilot-cheatsheet.html">Cheatsheet · Custom instructions</a>.</li></ol><blockquote><p>Cheap test for &quot;is there enough context?&quot;: <strong>make it restate first.</strong> &quot;Before you edit, summarize the current implementation in three sentences.&quot; If the restatement is wrong, do not let it touch code.</p></blockquote><h3 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h3><ul><li><strong>Always review generated code</strong>, especially auth checks, SQL string building, cryptography, and payments.</li><li><strong>Use automated tests as a guardrail</strong>: have Copilot write tests, confirm the tests are right, then let it change the implementation. The reverse is letting it grade its own exam.</li><li><strong>Public-code match</strong>: when you need to know whether a suggestion closely matches a public repo, use the <a href="https://docs.github.com/en/copilot/how-tos/get-code-suggestions/find-matching-code" target="_blank" rel="noreferrer">official matching log</a>.</li></ul><hr><h2 id="writing-code-in-the-editor-completion-inline-chat" tabindex="-1">Writing code in the editor (completion + inline Chat) <a class="header-anchor" href="#writing-code-in-the-editor-completion-inline-chat" aria-label="Permalink to &quot;Writing code in the editor (completion + inline Chat)&quot;">​</a></h2><p>When completion is the right tool:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>What to do</th></tr></thead><tbody><tr><td>Help generate code</td><td>Write a signature or a one-line comment of intent, wait for ghost text, <code>Tab</code></td></tr><tr><td>Refactor or fix</td><td>Select → <code>⌘I</code> inline Chat → say the target state</td></tr><tr><td>Explain</td><td>Select → <code>/explain</code> in Chat</td></tr><tr><td>Add comments</td><td>Select → <code>/doc</code></td></tr><tr><td>Generate tests</td><td>Select → <code>/tests</code>, optionally <code>/tests using the Jest framework</code></td></tr></tbody></table><p><strong>Comment-driven completion:</strong></p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ bad: vague intent, Copilot can only guess</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// handle users</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ good: inputs, outputs, and edges are stated</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Filter users active within the last 30 days with a verified email,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// return an array sorted by lastActiveAt descending</span></span></code></pre></div><hr><h2 id="working-in-the-terminal" tabindex="-1">Working in the terminal <a class="header-anchor" href="#working-in-the-terminal" aria-label="Permalink to &quot;Working in the terminal&quot;">​</a></h2><p>Two paths, pick by &quot;do I need multiple turns?&quot;:</p><p><strong>One-shot command help</strong> — <code>⌘I</code> inline Chat in the terminal, or <code>@terminal</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@terminal find the largest file in the src directory</span></span></code></pre></div><p>To debug the last failed command, pull it in with <code>#read</code> (<code>/terminalLastCommand</code>).</p><p><strong>Multi-turn terminal work</strong> — use <a href="./copilot-cheatsheet.html">Copilot CLI</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # start an interactive session</span></span></code></pre></div><p>Inside a session: <code>@ filename</code> to cite a file, <code>! command</code> to run a shell command, <code>Shift+Tab</code> to cycle standard / plan / autopilot.</p><p><strong>Only want to understand one command</strong> (no agent): do not install <code>gh copilot</code> — it is <a href="https://docs.github.com/en/copilot/how-tos/use-copilot-for-common-tasks/use-copilot-in-the-cli" target="_blank" rel="noreferrer">officially retired</a> and replaced by the standalone <code>copilot</code> CLI. The old <code>explain</code> / <code>suggest</code> commands are kept for reference in <a href="./copilot-cheatsheet.html#retired-gh-copilot">Cheatsheet · Retired <code>gh copilot</code></a>.</p><hr><h2 id="multi-file-changes-with-chat" tabindex="-1">Multi-file changes with Chat <a class="header-anchor" href="#multi-file-changes-with-chat" aria-label="Permalink to &quot;Multi-file changes with Chat&quot;">​</a></h2><p>Pick the mode by how sure you are (table: <a href="./copilot-cheatsheet.html">Cheatsheet · Mode selection</a>):</p><p><strong>Edit mode, standard flow:</strong></p><ol><li>Put the files in context (drag them in, or <code>#file:</code>)</li><li>State the goal <strong>and</strong> the fence: &quot;Split <code>calculateTotal</code> into three pure functions. <strong>Do not change its exported signature.</strong>&quot;</li><li>Review every diff. Accept or discard.</li></ol><p><strong>Agent mode, standard flow:</strong></p><ol><li>Ask for a plan first: <code>/plan</code>, or &quot;do not edit yet; list the steps&quot;</li><li>Confirm the plan, then let it run</li><li>Approve commands one by one (never approve a command you do not understand)</li><li>Run tests when it finishes</li></ol><blockquote><p>Recurring pitfall: in Agent mode, &quot;and tidy the formatting while you are at it&quot; produces a diff that is 90% noise. <strong>One job per turn.</strong></p></blockquote><hr><h2 id="reusing-prompt-files" tabindex="-1">Reusing prompt files <a class="header-anchor" href="#reusing-prompt-files" aria-label="Permalink to &quot;Reusing prompt files&quot;">​</a></h2><p>Save a task you keep re-describing as <code>.prompt.md</code>, then invoke it with a slash command.</p><p><strong>Where they live</strong> (full table: <a href="./copilot-cheatsheet.html">Cheatsheet · Prompt files</a>):</p><ul><li>Shared with the team: <code>.github/prompts/*.prompt.md</code> (commit it)</li><li>Personal, cross-repo: <code>.prompt.md</code> in a VS Code <a href="https://code.visualstudio.com/docs/configure/profiles" target="_blank" rel="noreferrer">profile</a>, syncable</li></ul><p><strong>Shape</strong>: frontmatter + Markdown body.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;agent&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;githubRepo&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;codebase&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Generate a new React form component&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Your goal is to generate a new React form component based on the templates in #githubRepo contoso/react-templates.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ask for the form name and fields if not provided.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Requirements for the form:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use form design system components: [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">design-system/Form.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">../docs/design-system/Form.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`react-hook-form\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for form state management</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Always define TypeScript types for your form data</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*uncontrolled*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> components using register</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`defaultValues\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to prevent unnecessary rerenders</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`yup\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for validation:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Create reusable validation schemas in separate files</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use TypeScript types to ensure type safety</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Customize UX-friendly validation rules</span></span></code></pre></div><p>Frontmatter fields:</p><ul><li><code>mode</code> — <code>ask</code> / <code>edit</code> / <code>agent</code> (concepts: <a href="./copilot-glossary.html">Glossary</a>)</li><li><code>tools</code> — allowed tools; list in <a href="./copilot-cheatsheet.html">Cheatsheet · Tool sets</a></li><li><code>description</code> — one-liner shown in the slash-command list</li></ul><p><strong>Body</strong>: Markdown, relative file links, <code>#</code> tool refs, and includes from other prompt files.</p><p><strong>Invoke</strong> in Chat with <code>/filename</code>, optionally with args:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/create-react-form: formName=MyForm</span></span></code></pre></div><p><strong>Debug</strong>: open the prompt file and hit the play button in the editor toolbar. Faster than trial-and-error in Chat.</p><p><strong>Migrating from Cursor</strong>: if you already have Cursor rules, point <code>chat.promptFilesLocations</code> at that directory instead of moving files.</p><hr><h2 id="capturing-project-conventions-custom-instructions" tabindex="-1">Capturing project conventions (custom instructions) <a class="header-anchor" href="#capturing-project-conventions-custom-instructions" aria-label="Permalink to &quot;Capturing project conventions (custom instructions)&quot;">​</a></h2><p>Rule of thumb: <strong>if you have written the same sentence in a prompt more than three times, it belongs in custom instructions.</strong></p><p>Start with one file, <code>.github/copilot-instructions.md</code>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Project conventions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeScript strict mode, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`any\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is not allowed (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`unknown\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> + type guards)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Function components + hooks only, never class components</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> State with Zustand, do not introduce Redux</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Tests with Vitest; assert objects with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`expect().toEqual()\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, not </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`toBe\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Conventional Commits for messages</span></span></code></pre></div><p>Authoring:</p><ul><li>Write <strong>&quot;don&#39;t&quot; and &quot;which one&quot;</strong>, not &quot;write good code&quot; — the latter does not constrain the model.</li><li><strong>One verifiable sentence per line.</strong> &quot;Be elegant&quot; is useless. &quot;Split functions longer than 40 lines&quot; is useful.</li><li><strong>Path-scoped</strong> rules go in <code>.github/instructions/**/*.instructions.md</code> with a glob in the frontmatter (for example, only <code>**/*.test.ts</code>).</li></ul><p>The five official scopes: <a href="./copilot-cheatsheet.html">Cheatsheet · Custom instructions</a>.</p><hr><h2 id="delegating-to-the-cloud-cloud-agent" tabindex="-1">Delegating to the cloud (Cloud agent) <a class="header-anchor" href="#delegating-to-the-cloud-cloud-agent" aria-label="Permalink to &quot;Delegating to the cloud (Cloud agent)&quot;">​</a></h2><p>Use it for work that is <strong>well-scoped, time-consuming, and does not need you watching</strong>. Typical path: describe the task on a GitHub Issue, assign Cloud agent; it opens a branch, edits, and (when you want) a PR.</p><p>It cannot see the constraints in your head. Write them down.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ bad: replace all the old API calls</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ good:</span></span>
<span class="line"><span>Replace every \`fetchLegacy(\` call under src/ with \`apiClient.request(\`.</span></span>
<span class="line"><span>Argument mapping: first argument \`url\` stays; in the second argument</span></span>
<span class="line"><span>\`options\`, rename \`body\` to \`data\`.</span></span>
<span class="line"><span>Do not touch tests/. When you are done, \`pnpm test\` must pass.</span></span></code></pre></div><p>As of the <a href="https://github.blog/changelog/2026-04-01-research-plan-and-code-with-copilot-cloud-agent/" target="_blank" rel="noreferrer">2026-04-01 changelog</a>, Cloud agent is no longer &quot;always open a PR&quot;:</p><ul><li>Ask it to <strong>research</strong> the repo before it writes code.</li><li>Ask it to produce an <strong>implementation plan</strong> and wait for your approval.</li><li>Let it work on a <strong>branch without opening a PR</strong>, review the diff, then click Create pull request — or say in the prompt that you want a PR at the end.</li></ul><p>On Copilot Business / Enterprise an admin must enable Cloud agent. Concepts and the local-Agent contrast: <a href="./copilot-glossary.html">Glossary · Cloud agent</a>.</p><hr><h2 id="github-spark-do-not-start-new-apps" tabindex="-1">GitHub Spark (do not start new apps) <a class="header-anchor" href="#github-spark-do-not-start-new-apps" aria-label="Permalink to &quot;GitHub Spark (do not start new apps)&quot;">​</a></h2><p>Spark was a natural-language micro-app builder on github.com. <strong>Do not start a new one.</strong></p><p>From <a href="https://github.blog/changelog/2026-08-04-upcoming-deprecation-of-github-spark-on-github-com/" target="_blank" rel="noreferrer">2026-08-04</a>:</p><ul><li>No new users, no new apps.</li><li>Existing users can open the Spark workbench, choose <code>…</code> → <strong>Create repository</strong>, and export before <strong>2026-08-31</strong>.</li><li>Apps you already deployed keep running. If the app calls <code>llm()</code>, that API died with GitHub Models on 2026-07-30 — replace it with your own provider.</li></ul><p>If you want a small web app today, use the IDE, Copilot CLI, or the Copilot app. Spark is an index node only; it does not get its own page.</p><hr><h2 id="connecting-external-tools-mcp" tabindex="-1">Connecting external tools (MCP) <a class="header-anchor" href="#connecting-external-tools-mcp" aria-label="Permalink to &quot;Connecting external tools (MCP)&quot;">​</a></h2><p>When Copilot needs your database, an internal API, or a third-party service, attach an MCP server. Its tools then show up in the <code>#</code> list and behave like built-in tools.</p><p><strong>Currency</strong>: GitHub App <strong>Copilot Extensions sunset on 2025-11-10</strong>. MCP is the official replacement. Old tutorials that say &quot;invoke the extension with <code>@extension-name</code>&quot; are dead. See <a href="./copilot-glossary.html">retired concepts</a>.</p><p>VS Code <strong>client-side</strong> Chat extensions (participants / tools via the VS Code extension API) <strong>are still supported</strong>. Dev guide: <a href="https://code.visualstudio.com/api/extension-guides/chat" target="_blank" rel="noreferrer">Chat extensions</a>.</p><p>Do not confuse MCP / the new <strong>Plugins</strong> pack (agents + skills + hooks) with the sunset GitHub App Extensions. <a href="./copilot-glossary.html">Glossary · Plugins</a>.</p><hr><h2 id="when-copilot-is-bad" tabindex="-1">When &quot;Copilot is bad&quot; <a class="header-anchor" href="#when-copilot-is-bad" aria-label="Permalink to &quot;When &quot;Copilot is bad&quot;&quot;">​</a></h2><p>Walk this list. Most problems die in the first two steps:</p><ol><li><strong>Is there enough context?</strong> Relevant files open? <code>#file:</code> used? Custom instructions written?</li><li><strong>Is the prompt checkable?</strong> Verifiable done-state? Explicit &quot;do not touch X&quot;?</li><li><strong>Is the mode right?</strong> Complaining that Ask mode &quot;won&#39;t edit files&quot; is this bucket.</li><li><strong>Is the model right?</strong> Available models differ by plan. Retry a hard task on another model.</li><li><strong>Only then is it a product bug</strong> — <a href="./copilot-cheatsheet.html">Cheatsheet · Troubleshooting</a>.</li></ol><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./copilot.html">Copilot tutorial</a> — what to install, how to start</li><li><a href="./copilot-cheatsheet.html">Copilot Cheatsheet</a> — keys / commands / config / plans</li><li><a href="./copilot-glossary.html">Glossary</a> — concepts and the retired list</li></ul>`,92)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
